#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v;
    v.push_back({a});
    v.push_back({b});
    v.push_back({c});

    sort(v.begin(), v.end());

    for (int x : v) {
        cout << x << endl;
    }
    return 0;
}
